 mg.page++;mg.at=Date.now();const start=mg.page*10;return manageReply('Lançamentos recentes (continuação):\n'+mg.rows.slice(start,start+10).map((r,i)=>`${start+i+1}. ${selectedSummary(r)}`).join('\n')+'\n\nEscolha pelo número: “editar '+(start+1)+'” ou “excluir '+(start+1)+'”.','gestao_listagem');
}
if(listRequest||((deletion||editing)&&!mg)){
 if(mg)delete state.management[manageKey];
 return [{json:{...x,route:'manage_list',manageKey,manageMode:deletion?'delete':editing?'edit':null}}];
}
if(mg&&deletion&&(/\b(?:todos|todas|tudo)\b/.test(l)||/\d+[.,]\d/.test(l)))return manageReply('De qual gasto você está falando? Pode me dizer a descrição ou o valor para eu conferir antes de excluir.');
if(mg&&(selectIndex!==null||deletion||editing||(mg.mode==='edit'&&/^(?:(?:o|a)\s+)?(?:valor|descricao|categoria|pagamento|data|tipo|pix|dinheiro|cartao|credito|debito)\b/.test(l)))){
 mg.at=Date.now();
 if(selectIndex!==null){
  if(selectIndex<1||selectIndex>mg.rows.length||selectIndex>(mg.page+1)*10)return manageReply('Esse número não está na lista exibida. Pode apontar pela descrição ou pelo valor, se preferir.');
  mg.selected=mg.rows[selectIndex-1];delete mg.proposal;
 }
 const record=mg.selected;
 if(!record)return manageReply('De qual lançamento você está falando? Pode me dizer a descrição, o valor ou apontar na lista.');
 if(editing)mg.mode='edit';else if(deletion)mg.mode='delete';
 if(deletion||mg.mode==='delete'){
  mg.mode='delete';mg.proposal={kind:'delete',record};
  return manageReply(`Excluir ${selectedSummary(record)}?\nIsso moverá o lançamento para a lixeira. Se estiver certo, me confirme. Se não, deixamos como está.`,'gestao_confirmacao');
 }
 if(editing||mg.mode==='edit'){
  mg.mode='edit';let changes;try{changes=changesFrom(t);}catch(e){return manageReply(e.message,'gestao_edicao');}
  if(!Object.keys(changes).length)return manageReply(`Selecionado: ${selectedSummary(record)}.\nO que você quer mudar nele? Pode me contar do seu jeito.`,'gestao_edicao');
  mg.proposal={kind:'update',record,changes};
  const labels={amount:'Valor',description:'Descrição',category:'Categoria',payment_details:'Pagamento',transaction_date:'Data',transaction_type:'Tipo'};
  return manageReply(`Alterar ${selectedSummary(record)}?\n`+Object.entries(changes).map(([k,v])=>`${labels[k]}: ${k==='amount'?br(v):k==='payment_details'?v.method+(v.installments>1?` em ${v.installments} parcelas`:''):v}`).join('\n')+'\n\nPosso salvar essas alterações? Se estiver certo, me confirme.','gestao_confirmacao');
 }
 return manageReply(`Selecionado: ${selectedSummary(record)}.\nDeseja editar ou excluir esse lançamento?`);
}
if(mg?.proposal){delete mg.proposal;mg.mode=null;}

for (const store of [state.pending,state.recent]) for (const [key,value] of Object.entries(store)) if (!value?.at || Date.now()-value.at > 30*60*1000) delete store[key];
const p=state.pending[x.chatId], rows=pendingRows(p);
const recent=state.recent[x.chatId];
const amounts=moneyIn(t), category=categoryFrom(t), payment=paymentFrom(t);
state.dialog??={};
const dialog=state.dialog[x.chatId];
const sameDialog=dialog&&dialog.senderId===x.senderId&&Date.now()-dialog.at<30*60*1000;
const close=message=>{delete state.pending[x.chatId];state.dialog[x.chatId]={senderId:x.senderId,at:Date.now(),closed:true,awaitingAction:null};return [{json:{...x,route:'reply',financialStatus:'encerrado',replyText:message}}];};
const explicitDecline=/^(?:nao,?\s+(?:quero|preciso|precisa|gostaria)(?:\s+(?:mais|nada|disso|isso|agora|de nada|mais nada|mais ajuda|(?:ver |consultar |do |de )?(?:o )?resumo(?: do mes)?|registrar (?:mais )?nada))?|nao,?\s+(?:era so isso|ja terminei)|ja (?:acabou|terminei)|chega|encerrar conversa)[.!\s]*$/.test(l);
const shortNo=/^(?:nao(?:,?\s*(?:obrigad[oa]|valeu|precisa|quero|por enquanto))?|agora nao|por enquanto nao|nao precisa|nao quero|deixa pra depois)[.!\s]*$/.test(l);
const goodbye=/^(?:obrigad[oa](?:,?\s*(?:era so isso|por enquanto e so|valeu))?|valeu|era so isso|por (?:hora|ora) e so|tchau|ate (?:mais|logo)|fechou)[.!\s]*$/.test(l);
if(shortNo||goodbye||explicitDecline)return close(p&&(shortNo||explicitDecline)?'Tudo bem! Cancelei a proposta pendente, sem registrar. 😊':'Combinado! Até mais. 😊');
const shortYes=/^(?:sim|pode ser|pode sim|quero|quero sim|claro|vamos|mostra|mostre|manda|pode mostrar|pode mandar)[.!\s]*$/.test(l);
if(shortYes&&sameDialog&&dialog.awaitingAction==='summary')return [{json:{...x,route:'summary'}}];
if(!p&&shortYes)return [{json:{...x,route:'reply',financialStatus:'esclarecimento',replyText:'Você quer consultar o resumo do mês ou registrar uma despesa?'}}];

const negative=/\b(?:nao|nunca|ainda|talvez|depois|se)\b/.test(l);
const question=/\?/.test(t) || /^(?:quanto|qual|como|quando|por que|sera|voce ja)\b/.test(l);
const explicitConfirm=/\b(?:confirmar lancamento|confirmo|confirmado|pode (?:registrar|salvar|anotar|lancar)|(?:registrar|registre|salve|anote|lance)(?:\s+(?:os|as|esses|essas|ambos|ambas|tudo|isso|ele|ela))?)\b/.test(l) || /^(?:sim|certo|esta certo|ta certo|tudo certo|ok|isso|pode sim|correto)[.!\s]*$/.test(l);
const referPending=/\b(?:os dois|as duas|ambos|ambas|esses|essas|comprovante|anexo|total|compras|lancamentos|confirmar lancamento)\b/.test(l);
const affirmative=/^(?:sim|certo|esta certo|ta certo|tudo certo|ok|isso|correto)\b/.test(l);
if (p && /\b(?:cancelar|cancele|desconsiderar|desconsidere|esquece|esqueca)\b/.test(l) && !question) {
  delete state.pending[x.chatId]; return reply('Cancelei a proposta pendente. Nenhum gasto dessa proposta foi registrado.');
}
if (/^(?:excluir|apagar|remover)\s+(?:o\s+)?(?:meu\s+)?(?:ultimo)\s+(?:lancamento|gasto|registro)[.!]?$/.test(l)) return [{json:{...x,route:'delete'}}];
const edit=t.match(/^(?:corrigir|alterar|trocar|mudar)\s+(?:a\s+)?(?:descrição|descricao)(?:\s+do\s+(?:último|ultimo)\s+lançamento)?\s+(?:para|por)\s+(.+)$/i);
if(edit)return [{json:{...x,route:'edit',description:clean(edit[1]).slice(0,180)}}];
if ((ai.intent==='resumo'&&!/\b(?:nao|depois|talvez)\b/.test(l)&&/\b(?:resumo|saldo|gastamos|gastos|despesas|receitas)\b/.test(l)) || /(?:quanto|total|resumo|saldo|gastamos|gastos).*(?:m[eê]s|mes|hoje|atual)|^\/(?:saldo|resumo)$/i.test(t)) return [{json:{...x,route:'summary'}}];
const exactConfirmation = /^confirmar lancamento[.!]?$/.test(l);
if (!p && exactConfirmation) return reply(recent?'A última proposta já foi registrada. Não criei outro lançamento.':'Não há proposta pendente para confirmar. Envie o comprovante novamente.');
if (p && rows.length) {
  const partial = rows.length>1 && /\b(?:primeiro|primeira|segundo|segunda|apenas um|somente um|so um|um deles|uma delas)\b/.test(l);
  const reference = ai.reference === 'pendente' || referPending || explicitConfirm || (amounts.length===0 && (category || payment));
  const canConfirm = !negative && !question && !partial && (explicitConfirm || (affirmative && (ai.intent==='confirmar_pendente' || (referPending && amounts.length===1))));
  if (reference && !negative) {
    if (partial) return reply('Tenho as compras pendentes separadas. Qual delas você quer registrar? Pode apontar pela descrição ou pelo valor.');
    const sum=total(rows);
    if (amounts.length && (amounts.length!==1 || cents(amounts[0].amount)!==cents(sum))) return reply(`O total das ${rows.length} compra(s) pendentes é ${br(sum)}, mas o valor informado é diferente. Qual valor devemos considerar?`);
    const transactions=rows.map(tx=>withMetadata(tx,category,payment));
    if (!question) { p.transactions=transactions;p.at=Date.now(); }
    if (canConfirm) return [{json:{...x,route:'transaction',transactions,tx:transactions[0],pendingConfirmation:true,proposalKey:p.sourceMessageId||x.messageId,intentUsed:ai.intent??null}}];
    if (negative) return reply('Mantive a proposta pendente, sem registrar. Quando quiser continuar, é só me falar.');
    return reply(`Tenho ${transactions.length} compra(s), total ${br(sum)}${category?` em ${category}`:''}${payment?` (${payment.method==='pix'?'Pix':payment.method})`:''}. Posso registrar ${transactions.length>1?'todas':'essa compra'}?`);
  }
  if (negative && (referPending || /registr|salv|anot|lanc/.test(l))) return reply('Mantive a proposta pendente, sem registrar. Quando quiser continuar, é só me falar.');
}
if (!p && recent && !negative) {
  const sum=Number(recent.total);
  const repeatsTotal=amounts.length===1 && cents(amounts[0].amount)===cents(sum) && /\b(?:total|certo|confirm|os dois|as duas|esses|essas)\b/.test(l);
  const refersToRecent=ai.reference==='ultimo_registro' && /\b(?:total|certo|confirm|os dois|as duas|esses|essas|ja|isso)\b/.test(l);
  if (repeatsTotal || refersToRecent || (explicitConfirm && referPending)) return reply(`Essas ${recent.transactions.length} compra(s) já foram registradas, total ${br(sum)}. Não criei lançamentos duplicados.`);
}
if (/^(?:oi|ola|ajuda|teste)[!. ]*$/.test(l)) return reply('Pode me mandar um gasto, uma foto ou perguntar sobre o resumo do mês. Se houver várias compras na imagem, eu guardo todas para você confirmar. Também posso listar os lançamentos para você escolher qual editar ou excluir.');
if (negative && amounts.length) return reply('Não registrei nenhum gasto, pois a mensagem não autoriza esse lançamento.');
if (question && amounts.length) return reply('Entendi como uma pergunta e não registrei nenhum gasto. Para lançar, envie a descrição com o valor e diga que deseja registrar.');
return [{json:{...x,route:'parse',intentUsed:ai.intent??null}}];
